import { categoryFields, sortProducts } from './catalog-ordering.js';

// A monthly lineup gates dated stock; publishing opens it to customer orders.
export function menuMonths(state, today) {
  const current = state.flavor_menus?.current_month || `${today.slice(0, 7)}-01`;
  const next = new Date(`${current}T12:00:00Z`);
  next.setUTCMonth(next.getUTCMonth() + 1);
  return [current, state.flavor_menus?.next_month || next.toISOString().slice(0, 10)];
}
export const monthLabel = month => new Intl.DateTimeFormat('en', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${month}T12:00:00Z`));
export const menuFor = (state, month) => state.flavor_menus?.menus?.find(menu => menu.month === month) || { flavor_ids: [], published: false };

export function renderFlavorMenus(state, { today, esc, disabled }) {
  const months = menuMonths(state, today), flavors = sortProducts(state.products.filter(p => p.kind === 'flavor'));
  const panels = months.map((month, i) => {
    const menu = menuFor(state, month), selected = flavors.filter(f => menu.flavor_ids.includes(f.id));
    return `<section class="panel flavor-menu-panel"><span class="eyebrow">${i ? 'Next month' : 'This month'}</span><h2>${esc(monthLabel(month))}</h2><span class="badge">${menu.published ? 'Published · orders enabled' : 'Hidden · orders disabled'}</span><div class="menu-flavor-list">${selected.length ? selected.map(f => `<button class="menu-flavor-tag" data-action="edit-flavor-menu" data-id="${esc(f.id)}">${esc(f.name)}</button>`).join('') : '<p class="muted">No flavors selected yet.</p>'}</div><form data-form="menu-visibility" data-month="${month}" data-current="${months[0]}"><div class="form-error" role="alert"></div><label class="check-field"><input type="checkbox" name="published" ${menu.published ? 'checked' : ''} ${disabled}><span>Publish this lineup and allow orders for its dates</span></label><button class="button button-secondary" type="submit" ${disabled}>Save visibility</button></form></section>`;
  }).join('');
  return `<div class="flavor-menu-panels">${panels}</div><section class="panel menu-collection"><div class="section-heading"><div><h2>Full collection</h2><p class="muted">All flavor records, including hidden drafts. Customers only see flavors that are not hidden.</p></div><span class="badge">${flavors.length} flavors</span></div><div class="menu-collection-grid">${flavors.map(f => `<article class="menu-collection-card"><h3>${esc(f.name)}</h3><p>${esc(f.description || 'Add a description to introduce this flavor.')}</p><div class="menu-placements">${f.collection_hidden ? '<span class="badge">Hidden · unavailable</span>' : ''}${months.map(month => menuFor(state, month).flavor_ids.includes(f.id) ? `<span class="badge">${esc(monthLabel(month))}</span>` : '').join('') || '<span class="muted">Collection only</span>'}</div><button class="button button-quiet" data-action="edit-flavor-menu" data-id="${esc(f.id)}">${state.role === 'staff' ? 'View flavor' : 'Edit flavor & placement'} →</button></article>`).join('') || '<p class="muted">Add your first flavor to start the collection.</p>'}</div></section>`;
}

export function flavorMenuFields(state, id, { today, esc, input, textarea, select, option, check, disabled }) {
  const p = state.products.find(p => p.id === id && p.kind === 'flavor') || {};
  const months = menuMonths(state, today);
  return `<input type="hidden" name="id" value="${esc(p.id || '')}"><input type="hidden" name="expected_month" value="${months[0]}">${input('name', 'Flavor name', p.name, 'text', 'required maxlength="160"')}${input('tagline', 'Short description', p.tagline || window.ELIO_CONTENT?.flavors.find(f => f.id === p.slug)?.line || '', 'text', 'maxlength="100"', 'For example: Toasted and mellow.')}${textarea('description', 'Flavor description', p.description, 'Shown when a customer opens this flavor.', 'maxlength="6000" rows="4"')}${categoryFields(p,state.categories.filter(c=>c.scope==='flavors'),esc,disabled)}<section class="subsection"><h3>Photo</h3><input type="hidden" name="photos" value="${esc(JSON.stringify(p.photos || []))}"><div id="menu-photo-preview">${p.photos?.[0] && /^(https?:\/\/|assets\/)/.test(p.photos[0]) ? `<img src="${esc(p.photos[0])}" alt="Current flavor cover" style="width:110px;height:90px;object-fit:cover;border-radius:8px">` : ''}</div>${input('cover_photo','Upload / replace cover photo','','file','id="menu-cover-photo" accept="image/jpeg,image/png,image/webp" '+disabled,'JPEG, PNG, or WebP, up to 5 MB. Save the flavor to use this photo.')}</section><section class="subsection"><h3>Visibility & monthly lineups</h3>${check('hidden','Hidden — remove from collection and disable new orders',p.collection_hidden === true,disabled)}${months.map((month,i) => check(i ? 'next_month' : 'current_month', `${i ? 'Next month' : 'This month'} · ${monthLabel(month)}`, menuFor(state,month).flavor_ids.includes(p.id), disabled)).join('')}<p class="help-text">Leave both unchecked for the full collection only. You can select both. Hidden monthly lineups stay private and unavailable to order until published. Removing a flavor clears its unsold quantities for that month; existing orders are kept.</p></section><p class="notice">A flavor needs a published monthly lineup, enabled product settings, and daily stock to be ordered. Shop closures always apply. Manage surcharges in Flavors and stock in Daily quantities.${p.id ? '' : ' New flavors start unavailable for ordering until you configure them.'}</p>`;
}
